"use client";

import { useEffect, useRef, useCallback, useState } from "react";
import createGlobe from "cobe";

/* New Delhi coordinates */
const DELHI_LAT = 28.6139;
const DELHI_LNG = 77.209;

export function CobeGlobe() {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const containerRef = useRef<HTMLDivElement>(null);
  const pointerDown = useRef(false);
  const pointerX = useRef(0);
  const phi = useRef(1.2);
  const globeRef = useRef<ReturnType<typeof createGlobe> | null>(null);
  const [visible, setVisible] = useState(false);
  const hasInitialized = useRef(false);

  const initGlobe = useCallback(() => {
    const canvas = canvasRef.current;
    const container = containerRef.current;
    if (!canvas || !container) return;

    // Destroy previous instance
    if (globeRef.current) {
      globeRef.current.destroy();
      globeRef.current = null;
    }

    const width = container.clientWidth;
    if (width === 0) return;

    const dpr = Math.min(window.devicePixelRatio, 1.5);
    const pixelWidth = Math.floor(width * dpr);

    try {
      globeRef.current = createGlobe(canvas, {
        devicePixelRatio: dpr,
        width: pixelWidth,
        height: pixelWidth,
        phi: 1.2,
        theta: 0.15,
        dark: 1,
        diffuse: 1.2,
        mapSamples: 16000,
        mapBrightness: 10,
        baseColor: [0.9, 0.9, 0.92],
        markerColor: [1.0, 0.27, 0.0],
        glowColor: [0.15, 0.06, 0.0],
        markers: [{ location: [DELHI_LAT, DELHI_LNG], size: 0.15 }],
        onRender: (state) => {
          if (!pointerDown.current) {
            phi.current += 0.003;
          }
          state.phi = phi.current;
          state.width = pixelWidth;
          state.height = pixelWidth;
        },
      });

      hasInitialized.current = true;
      setVisible(true);
    } catch {
      // If cobe fails, retry once after a delay
      setTimeout(() => {
        try {
          globeRef.current = createGlobe(canvas, {
            devicePixelRatio: 1, // fallback to 1x DPR
            width: width,
            height: width,
            phi: 1.2,
            theta: 0.15,
            dark: 1,
            diffuse: 1.2,
            mapSamples: 16000,
            mapBrightness: 10,
            baseColor: [0.9, 0.9, 0.92],
            markerColor: [1.0, 0.27, 0.0],
            glowColor: [0.15, 0.06, 0.0],
            markers: [{ location: [DELHI_LAT, DELHI_LNG], size: 0.15 }],
            onRender: (state) => {
              if (!pointerDown.current) {
                phi.current += 0.003;
              }
              state.phi = phi.current;
            },
          });
          setVisible(true);
        } catch {
          // Silent fail — no globe, but no crash
        }
      }, 2000);
    }
  }, []);

  /* Use IntersectionObserver to only init when in viewport.
     This gives the R3F torus context time to release GPU
     resources and ensures cobe gets a clean WebGL context. */
  useEffect(() => {
    const container = containerRef.current;
    if (!container) return;

    const observer = new IntersectionObserver(
      (entries) => {
        if (entries[0].isIntersecting && !hasInitialized.current) {
          // Delay slightly after becoming visible
          setTimeout(initGlobe, 500);
        }
      },
      { threshold: 0.1 }
    );

    observer.observe(container);

    // Also set a fallback timer in case observer doesn't trigger
    const fallbackTimer = setTimeout(() => {
      if (!hasInitialized.current) {
        initGlobe();
      }
    }, 5000);

    const onResize = () => {
      if (hasInitialized.current) {
        setTimeout(initGlobe, 300);
      }
    };
    window.addEventListener("resize", onResize);

    return () => {
      observer.disconnect();
      clearTimeout(fallbackTimer);
      window.removeEventListener("resize", onResize);
      if (globeRef.current) {
        globeRef.current.destroy();
        globeRef.current = null;
      }
    };
  }, [initGlobe]);

  // Pointer drag
  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;

    const onPointerDown = (e: PointerEvent) => {
      pointerDown.current = true;
      pointerX.current = e.clientX;
    };
    const onPointerUp = () => {
      pointerDown.current = false;
    };
    const onPointerMove = (e: PointerEvent) => {
      if (pointerDown.current) {
        const delta = e.clientX - pointerX.current;
        pointerX.current = e.clientX;
        phi.current += delta / 200;
      }
    };

    canvas.addEventListener("pointerdown", onPointerDown);
    window.addEventListener("pointerup", onPointerUp);
    window.addEventListener("pointermove", onPointerMove);

    return () => {
      canvas.removeEventListener("pointerdown", onPointerDown);
      window.removeEventListener("pointerup", onPointerUp);
      window.removeEventListener("pointermove", onPointerMove);
    };
  }, []);

  return (
    <div
      ref={containerRef}
      style={{
        width: "100%",
        maxWidth: "420px",
        aspectRatio: "1",
        margin: "0 auto",
        position: "relative",
      }}
    >
      <canvas
        ref={canvasRef}
        style={{
          width: "100%",
          height: "100%",
          cursor: "grab",
          contain: "layout paint size",
          opacity: visible ? 1 : 0,
          transition: "opacity 0.8s ease",
        }}
      />
    </div>
  );
}
